@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

owl:Class rdfs:subClassOf rdfs:Class .

owl:DatatypeProperty rdfs:subClassOf rdf:Property .

calidad:EnlaceConEvidencia a sh:NodeShape ;
    rdfs:label "Cada enlace dice de qué fuente sale y por qué" ;
    rdfs:comment "Todo lo que une o corrige Rastro tiene una regla. Si además no tiene su fuente y su evidencia, no se puede auditar." ;
    sh:property [ sh:message "No dice de qué fuente sale." ;
            sh:minCount 1 ;
            sh:path prov:wasDerivedFrom ],
        [ sh:message "No tiene evidencia." ;
            sh:minCount 1 ;
            sh:minLength 1 ;
            sh:path energia:sourceText ] ;
    sh:targetSubjectsOf energia:rule .

