            sh:message "No es de una sola empresa." ;
            sh:minCount 1 ;
            sh:path energia:partner ],
        [ sh:maxCount 1 ;
            sh:message "No es de una sola concesión." ;
            sh:minCount 1 ;
            sh:path energia:inConcession ] ;
