reglas.shacl:
@prefix calidad: <https://w3id.org/rastro/energia/calidad#> .
@prefix energia: <https://w3id.org/rastro/energia#> .
@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix prov: <http://www.w3.org/ns/prov#> .
@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

owl:Class rdfs:subClassOf rdfs:Class .

owl:DatatypeProperty rdfs:subClassOf rdf:Property .

calidad:Prediccion a sh:NodeShape ;
    rdfs:label "Cada predicción sale de un inicio de pozo y cae dentro de su rango" ;
    rdfs:comment "Sin el inicio del pozo, la predicción no se puede explicar; fuera de su rango, el rango no dice nada." ;
    sh:property [ sh:lessThanOrEquals energia:predictedHigh ;
            sh:message "La predicción es mayor que el máximo del rango." ;
            sh:minCount 1 ;
            sh:path energia:predictedGas ],
        [ sh:message "No dice de qué inicio de pozo sale." ;
            sh:path prov:used ;
            sh:qualifiedMaxCount 1 ;
            sh:qualifiedMinCount 1 ;
            sh:qualifiedValueShape [ sh:class energia:WellStart ] ],
        [ sh:lessThanOrEquals energia:predictedGas ;
            sh:message "El mínimo del rango es mayor que la predicción." ;
            sh:minCount 1 ;
            sh:path energia:predictedLow ] ;
    sh:targetClass energia:Prediction .

